import React, { useState, useRef, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { useLocation, useNavigate } from 'react-router-dom';
import Header from '../../components/ui/Header';
import Footer from '../../components/ui/Footer';
import Button from '../../components/ui/Button';
import Icon from '../../components/AppIcon';
import Input from '../../components/ui/Input';
import ThemeToggle from '../../components/ui/ThemeToggle';
import { supabaseService } from '../../services/supabaseService';
import { updateUserDetails } from '../../store/authSlice';
import { useToast } from '../../contexts/ToastContext';
import ConfirmationModal from '../../components/ui/ConfirmationModal';
import Modal from '../../components/ui/Modal';
import MfaSettings from './components/MfaSettings';
import RealWorldWins from './components/RealWorldWins';
import { cn } from '../../utils/cn';

const Profile = () => {
    const { user } = useSelector((state) => state.auth);
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const location = useLocation();
    const { addToast } = useToast();
    const fileInputRef = useRef(null);

    const [activeTab, setActiveTab] = useState(location.state?.tab || 'account');
    const [isSaving, setIsSaving] = useState(false);
    const [isUploading, setIsUploading] = useState(false);
    const [showSuccessModal, setShowSuccessModal] = useState(false);
    const [isPasswordModalOpen, setIsPasswordModalOpen] = useState(false);
    const [isTokenModalOpen, setIsTokenModalOpen] = useState(false);
    const [userEnteredToken, setUserEnteredToken] = useState('');
    const [tokenError, setTokenError] = useState('');
    const [passwordForm, setPasswordForm] = useState({
        currentPassword: '',
        newPassword: '',
        confirmPassword: ''
    });
    const [passwordError, setPasswordError] = useState('');
    const [isPinModalOpen, setIsPinModalOpen] = useState(false);
    const [pinForm, setPinForm] = useState({
        currentPin: '',
        newPin: '',
        confirmPin: ''
    });
    const [pinError, setPinError] = useState('');

    const [profileForm, setProfileForm] = useState({
        name: user?.name || '',
        email: user?.email || '',
        bio: user?.bio || 'Passionate about educational opportunities and global impact.',
        avatar: user?.avatar || '',
        notifications: user?.notifications || {
            email: true,
            whatsapp: false,
            browser: true
        }
    });

    useEffect(() => {
        if (location.state?.tab) {
            setActiveTab(location.state.tab);
        }
    }, [location.state]);

    const handleUpdateProfile = async (e) => {
        e.preventDefault();
        setIsSaving(true);
        try {
            const updates = {
                full_name: profileForm.name,
                bio: profileForm.bio,
                avatar_url: profileForm.avatar,
                updated_at: new Date()
            };
            await supabaseService.updateProfile(user.id, updates);
            dispatch(updateUserDetails({
                name: profileForm.name,
                bio: profileForm.bio,
                avatar: profileForm.avatar
            }));
            addToast('Profile updated successfully!', 'success');
        } catch (error) {
            console.error('Error updating profile:', error);
            addToast(`Failed to update profile: ${error.message}`, 'error');
        } finally {
            setIsSaving(false);
        }
    };

    const handleImageUpload = async (e) => {
        const file = e.target.files[0];
        if (!file) return;
        setIsUploading(true);
        try {
            const publicUrl = await supabaseService.uploadImage(file);
            setProfileForm(prev => ({ ...prev, avatar: publicUrl }));
            await supabaseService.updateProfile(user.id, { avatar_url: publicUrl });
            dispatch(updateUserDetails({ avatar: publicUrl }));
            addToast('Profile picture updated!', 'success');
        } catch (error) {
            addToast('Failed to upload image', 'error');
        } finally {
            setIsUploading(false);
        }
    };

    const handleInitiatePasswordChange = async () => {
        setIsSaving(true);
        try {
            await supabaseService.sendReauthenticationToken();
            setUserEnteredToken('');
            setTokenError('');
            setIsTokenModalOpen(true);
            addToast(`Verification code sent to your email.`, 'info');
        } catch (error) {
            addToast('Failed to send verification code', 'error');
        } finally {
            setIsSaving(false);
        }
    };

    const handleVerifyToken = (e) => {
        e.preventDefault();
        if (userEnteredToken.trim().length < 6) {
            setTokenError('Please enter the full code.');
            return;
        }
        setIsTokenModalOpen(false);
        setIsPasswordModalOpen(true);
    };

    const handleUpdatePassword = async (e) => {
        e.preventDefault();
        if (passwordForm.newPassword !== passwordForm.confirmPassword) {
            setPasswordError('Passwords do not match');
            return;
        }
        setIsSaving(true);
        try {
            await supabaseService.updatePassword(passwordForm.newPassword, userEnteredToken, passwordForm.currentPassword);
            addToast('Password updated successfully!', 'success');
            setIsPasswordModalOpen(false);
            setPasswordForm({ currentPassword: '', newPassword: '', confirmPassword: '' });
        } catch (error) {
            addToast(`Failed to update password: ${error.message}`, 'error');
        } finally {
            setIsSaving(false);
        }
    };

    const handleUpdatePin = async (e) => {
        e.preventDefault();
        if (pinForm.newPin.length !== 4) {
            setPinError('PIN must be exactly 4 digits');
            return;
        }
        if (pinForm.newPin !== pinForm.confirmPin) {
            setPinError('PINs do not match');
            return;
        }
        setIsSaving(true);
        try {
            await supabaseService.updateSecurityPin(pinForm.newPin);
            dispatch(updateUserDetails({ 
                user_metadata: { ...user?.user_metadata, security_pin: pinForm.newPin } 
            }));
            addToast('Security PIN updated successfully!', 'success');
            setIsPinModalOpen(false);
            setPinForm({ currentPin: '', newPin: '', confirmPin: '' });
            setPinError('');
        } catch (error) {
            addToast(`Failed to update PIN: ${error.message}`, 'error');
        } finally {
            setIsSaving(false);
        }
    };

    const navigationGroups = [
        {
            group: 'SETTINGS',
            tabs: [
                { id: 'account', label: 'Account Profile', icon: 'UserCircle' },
                { id: 'wins', label: 'Real World Wins', icon: 'Award' },
                { id: 'preferences', label: 'Preferences', icon: 'Settings' },
                { id: 'security', label: 'Security', icon: 'Shield' }
            ]
        }
    ];

    return (
        <div className="min-h-screen bg-background flex flex-col font-sans">
            <Header />

            <div className="flex-1 flex flex-col lg:flex-row">
                <aside className="w-full lg:w-72 bg-card border-r border-border p-8 space-y-8 h-auto lg:h-[calc(100vh-80px)] lg:sticky lg:top-20">
                    <div>
                        <h2 className="text-2xl font-black italic tracking-tighter uppercase mb-2">Settings</h2>
                        <p className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground opacity-60">Personal Control Center</p>
                    </div>

                    <nav className="space-y-2">
                        {navigationGroups[0].tabs.map((tab) => (
                            <button
                                key={tab.id}
                                onClick={() => setActiveTab(tab.id)}
                                className={cn(
                                    "w-full flex items-center gap-3 px-4 py-3 rounded-2xl text-xs font-black italic transition-all group",
                                    activeTab === tab.id ? 'bg-primary/5 text-primary border border-primary/20' : 'text-muted-foreground hover:text-foreground hover:bg-muted/50'
                                )}
                            >
                                <Icon name={tab.icon} size={18} />
                                <span className="uppercase tracking-widest">{tab.label}</span>
                            </button>
                        ))}
                    </nav>

                    <div className="pt-8 border-t border-border mt-auto">
                        <Button variant="outline" fullWidth className="text-destructive border-destructive/20 hover:bg-destructive hover:text-white rounded-xl font-black italic uppercase text-[10px] tracking-widest h-12" onClick={() => { dispatch({ type: 'auth/logout' }); navigate('/'); }}>
                            <Icon name="LogOut" size={16} className="mr-2" /> SIGN OUT
                        </Button>
                    </div>
                </aside>

                <main className="flex-1 p-4 md:p-12 max-w-5xl">
                    {/* Compact Profile Header */}
                    <div className="flex flex-col md:flex-row items-center gap-8 mb-12 bg-card border border-border p-8 rounded-[3rem] shadow-sm relative overflow-hidden">
                        <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-primary via-secondary to-brand-blue" />
                        <div className="relative group shrink-0">
                            <div className="w-24 h-24 md:w-32 md:h-32 rounded-full bg-gradient-to-br from-primary to-secondary p-1">
                                <div className="w-full h-full rounded-full bg-card flex items-center justify-center overflow-hidden relative">
                                    {profileForm.avatar ? (
                                        <img src={profileForm.avatar} alt={user?.name} className="w-full h-full object-cover" />
                                    ) : (
                                        <span className="text-4xl font-bold bg-gradient-to-br from-primary to-secondary bg-clip-text text-transparent">{user?.name?.[0]?.toUpperCase()}</span>
                                    )}
                                    {isUploading && <div className="absolute inset-0 bg-black/40 flex items-center justify-center"><Icon name="RefreshCw" className="animate-spin text-white" /></div>}
                                </div>
                            </div>
                            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
                            <button onClick={() => fileInputRef.current.click()} className="absolute bottom-1 right-1 p-2 bg-secondary text-white rounded-full shadow-lg hover:scale-110 transition-all"><Icon name="Camera" size={16} /></button>
                        </div>
                        <div className="text-center md:text-left">
                            <h1 className="text-3xl font-black italic tracking-tighter uppercase mb-1">{user?.name}</h1>
                            <p className="text-muted-foreground font-bold italic mb-4">{user?.email}</p>
                            <div className="flex flex-wrap justify-center md:justify-start gap-4">
                                <span className="px-3 py-1 bg-primary/5 text-primary border border-primary/20 rounded-full text-[10px] font-black uppercase tracking-widest">Global Citizen</span>
                                <span className="px-3 py-1 bg-muted text-muted-foreground rounded-full text-[10px] font-black uppercase tracking-widest">Account Verified</span>
                            </div>
                        </div>
                    </div>

                    <div className="min-h-[50vh] animate-in fade-in slide-in-from-bottom-4 duration-500">
                        {activeTab === 'account' && (
                            <form onSubmit={handleUpdateProfile} className="space-y-8">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <Input label="Display Name" value={profileForm.name} onChange={(e) => setProfileForm({ ...profileForm, name: e.target.value })} />
                                    <div className="space-y-1">
                                        <Input label="Email (Verified)" value={profileForm.email} disabled />
                                        <div className="flex items-center gap-2 ml-2">
                                            <span className="text-[10px] font-black uppercase tracking-widest text-muted-foreground opacity-70 italic">Need to change this?</span>
                                            <button 
                                                type="button" 
                                                onClick={() => navigate('/contact#contact-form')}
                                                className="text-[10px] font-black uppercase tracking-widest text-primary hover:underline flex items-center gap-1"
                                            >
                                                <Icon name="ExternalLink" size={10} />
                                                CONTACT SUPPORT
                                            </button>
                                        </div>
                                    </div>
                                </div>
                                <div className="space-y-2">
                                    <label className="text-xs font-black uppercase tracking-widest text-primary/60 ml-2">Bio</label>
                                    <textarea className="w-full p-6 bg-background dark:bg-muted/20 border border-border rounded-3xl focus:ring-2 focus:ring-primary outline-none transition-all min-h-[150px] font-bold italic text-foreground placeholder:text-muted-foreground/50" value={profileForm.bio} onChange={(e) => setProfileForm({ ...profileForm, bio: e.target.value })} placeholder="Tell the world your story..." />
                                </div>
                                <div className="flex justify-end"><Button type="submit" variant="primary" iconName="Save" loading={isSaving} className="rounded-2xl px-8 font-black italic uppercase tracking-widest h-14 shadow-xl shadow-primary/20">SAVE PROFILE</Button></div>
                            </form>
                        )}

                        {activeTab === 'wins' && <RealWorldWins userId={user?.id} />}

                        {activeTab === 'preferences' && (
                            <div className="space-y-8">
                                <div className="p-8 bg-card border border-border rounded-[2.5rem] flex items-center justify-between shadow-sm">
                                    <div><h3 className="text-lg font-black italic uppercase tracking-tight">Interface Theme</h3><p className="text-xs text-muted-foreground font-medium italic">Personalize the visual density of your command center.</p></div>
                                    <ThemeToggle />
                                </div>
                                <div className="space-y-4">
                                    <h3 className="text-sm font-black italic uppercase tracking-widest text-primary/60 ml-4">Notification Protocols</h3>
                                    {Object.entries(profileForm.notifications).map(([key, value]) => (
                                        <div key={key} className="flex items-center justify-between p-6 bg-card border border-border rounded-3xl hover:border-primary/30 transition-all">
                                            <div className="flex items-center gap-4">
                                                <div className="p-3 bg-muted rounded-2xl"><Icon name={key === 'email' ? 'Mail' : 'Bell'} size={20} className="text-primary" /></div>
                                                <div><p className="text-sm font-black italic uppercase">{key} ALERTS</p><p className="text-[10px] text-muted-foreground font-bold italic">Synchronize updates via {key}.</p></div>
                                            </div>
                                            <button onClick={() => setProfileForm({...profileForm, notifications: {...profileForm.notifications, [key]: !value}})} className={cn("w-14 h-7 rounded-full transition-all relative border border-transparent", value ? "bg-secondary" : "bg-muted")}>
                                                <div className={cn("absolute top-1 w-5 h-5 bg-white rounded-full shadow-lg transition-all", value ? "right-1" : "left-1")} />
                                            </button>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        {activeTab === 'security' && (
                            <div className="space-y-8">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div className="p-8 bg-card border border-border rounded-[2.5rem] space-y-6 shadow-sm">
                                        <div className="flex items-center gap-4"><div className="p-3 bg-orange-500/10 rounded-2xl text-orange-500"><Icon name="Lock" size={24} /></div><div><h4 className="font-black italic uppercase tracking-tight">Access Key</h4><p className="text-[10px] font-bold text-muted-foreground uppercase">Update your security credential</p></div></div>
                                        <Button variant="outline" fullWidth className="rounded-xl h-12 font-black italic uppercase text-[10px] tracking-widest" onClick={handleInitiatePasswordChange}>CHANGE PASSWORD</Button>
                                    </div>
                                    <div className="p-8 bg-card border border-border rounded-[2.5rem] space-y-6 shadow-sm">
                                        <div className="flex items-center gap-4"><div className="p-3 bg-primary/10 rounded-2xl text-primary"><Icon name="Lock" size={24} /></div><div><h4 className="font-black italic uppercase tracking-tight">Security Vault PIN</h4><p className="text-[10px] font-bold text-muted-foreground uppercase">Used for session inactivity locks</p></div></div>
                                        <Button variant="outline" fullWidth className="rounded-xl h-12 font-black italic uppercase text-[10px] tracking-widest" onClick={() => setIsPinModalOpen(true)}>CHANGE VAULT PIN</Button>
                                    </div>
                                    <div className="p-8 bg-card border border-border rounded-[2.5rem] space-y-6 shadow-sm"><MfaSettings /></div>
                                </div>
                                <div className="p-8 border border-destructive/20 bg-destructive/5 rounded-[2.5rem] flex flex-col md:flex-row items-center justify-between gap-6">
                                    <div><h3 className="text-destructive font-black italic uppercase tracking-tight">Account Termination</h3><p className="text-xs text-muted-foreground font-medium italic">Permanently erase your identity and progress from the LUC ecosystem.</p></div>
                                    <Button variant="outline" className="text-destructive border-destructive/20 hover:bg-destructive hover:text-white rounded-xl font-black italic uppercase text-[10px] tracking-widest px-8">TERMINATE IDENTITY</Button>
                                </div>
                            </div>
                        )}
                    </div>
                </main>
            </div>
            <Footer />

            <Modal isOpen={isTokenModalOpen} onClose={() => setIsTokenModalOpen(false)} title="SECURITY SHIELD VERIFICATION">
                <div className="space-y-6">
                    <p className="text-sm font-bold italic text-muted-foreground text-center">Enter the 8-digit protocol code sent to your verified email.</p>
                    <Input placeholder="E.G. 12345678" value={userEnteredToken} onChange={(e) => setUserEnteredToken(e.target.value)} error={tokenError} className="text-center font-black italic tracking-widest text-2xl h-16" />
                    <Button variant="primary" fullWidth size="lg" onClick={handleVerifyToken} className="rounded-2xl h-14 font-black italic uppercase tracking-widest">VERIFY PROTOCOL</Button>
                </div>
            </Modal>

            <Modal isOpen={isPasswordModalOpen} onClose={() => setIsPasswordModalOpen(false)} title="GENERATE NEW ACCESS KEY">
                <div className="space-y-4">
                    <Input label="Current Key" type="password" value={passwordForm.currentPassword} onChange={(e) => setPasswordForm({ ...passwordForm, currentPassword: e.target.value })} />
                    <div className="h-px bg-border my-2" />
                    <Input label="New Key" type="password" value={passwordForm.newPassword} onChange={(e) => setPasswordForm({ ...passwordForm, newPassword: e.target.value })} />
                    <Input label="Confirm New Key" type="password" value={passwordForm.confirmPassword} onChange={(e) => setPasswordForm({ ...passwordForm, confirmPassword: e.target.value })} error={passwordError} />
                    <Button variant="primary" fullWidth size="lg" onClick={handleUpdatePassword} loading={isSaving} className="rounded-2xl h-14 font-black italic uppercase tracking-widest mt-4">UPDATE SECURITY KEY</Button>
                </div>
            </Modal>

            <Modal isOpen={isPinModalOpen} onClose={() => setIsPinModalOpen(false)} title="CONFIGURE SECURITY VAULT PIN">
                <div className="space-y-6">
                    <div className="text-center">
                        <p className="text-sm font-bold italic text-muted-foreground">This PIN is required to unlock your session after periods of inactivity.</p>
                    </div>
                    
                    <div className="space-y-4">
                        <div className="grid grid-cols-2 gap-4">
                            <Input 
                                label="New 4-Digit PIN" 
                                type="password" 
                                maxLength={4}
                                placeholder="****"
                                value={pinForm.newPin} 
                                onChange={(e) => setPinForm({ ...pinForm, newPin: e.target.value.replace(/\D/g, '') })} 
                                className="text-center font-black tracking-[0.5em] text-xl"
                            />
                            <Input 
                                label="Confirm PIN" 
                                type="password" 
                                maxLength={4}
                                placeholder="****"
                                value={pinForm.confirmPin} 
                                onChange={(e) => setPinForm({ ...pinForm, confirmPin: e.target.value.replace(/\D/g, '') })} 
                                className="text-center font-black tracking-[0.5em] text-xl"
                                error={pinError}
                            />
                        </div>
                    </div>

                    <div className="bg-primary/5 p-4 rounded-2xl border border-primary/10">
                        <p className="text-[10px] font-black uppercase tracking-widest text-primary text-center">
                            Note: Choose a PIN that is easy for you to remember but hard for others to guess.
                        </p>
                    </div>

                    <Button 
                        variant="primary" 
                        fullWidth 
                        size="lg" 
                        onClick={handleUpdatePin} 
                        loading={isSaving} 
                        className="rounded-2xl h-14 font-black italic uppercase tracking-widest"
                    >
                        ACTIVATE NEW PIN
                    </Button>
                </div>
            </Modal>
        </div>
    );
};

export default Profile;
